{
  "scenes": [
    {
      "scene_id": "S1",
      "name": "乱桌困境",
      "summary": "杂乱桌面与注意力被打断的对比开场"
    },
    {
      "scene_id": "S2",
      "name": "三步整理",
      "summary": "清空视觉噪音、给东西定位置、留出空白区"
    },
    {
      "scene_id": "S3",
      "name": "完成后收尾",
      "summary": "整洁桌面与专注工作的收束画面"
    }
  ],
  "shots": [
    {
      "shot_id": "SH-01",
      "scene": "S1",
      "description": "俯拍杂乱桌面，堆满纸张、水杯、耳机；镜头缓慢推进，字幕打出开场钩子。"
    },
    {
      "shot_id": "SH-02",
      "scene": "S1",
      "description": "中景跟拍主角坐下，手在桌面上犹豫寻找物品，手机通知亮起，画面轻微抖动。"
    },
    {
      "shot_id": "SH-03",
      "scene": "S2",
      "description": "特写双手把无关物品推到桌子一侧，形成“待处理区”，叠加快剪节奏。"
    },
    {
      "shot_id": "SH-04",
      "scene": "S2",
      "description": "分屏演示常用物品放触手可及处、低频物品收进抽屉，配字幕“一秒拿到”。"
    },
    {
      "shot_id": "SH-05",
      "scene": "S2",
      "description": "桌面右侧空出 A4 纸大小的空白区，放上待处理纸张，光线干净明亮。"
    },
    {
      "shot_id": "SH-06",
      "scene": "S3",
      "description": "正面平拍整洁桌面：电脑、笔记本、一支笔；主角呼吸放松，开始专注写作。"
    }
  ]
}
